import { HostTree } from '@angular-devkit/schematics';
import {
  SchematicTestRunner,
  UnitTestTree,
} from '@angular-devkit/schematics/testing/index.js';
import { fileURLToPath } from 'node:url';

export const collectionPath = fileURLToPath(
  new URL('../dist/schematics/collection.json', import.meta.url),
);

export function createRunner(): SchematicTestRunner {
  return new SchematicTestRunner('nest-monorepo-kafka', collectionPath);
}

/** A minimal project as generated by `nest new` (Nest 12 is ESM; pass esm=false for Nest 11-style CJS). */
export function createNestProject({ esm = true } = {}): UnitTestTree {
  const tree = new UnitTestTree(new HostTree());
  const ext = esm ? '.js' : '';
  tree.create(
    'package.json',
    JSON.stringify(
      {
        name: 'test-app',
        ...(esm ? { type: 'module' } : {}),
        scripts: { build: 'nest build' },
        dependencies: {
          '@nestjs/common': '^12.0.1',
          '@nestjs/core': '^12.0.1',
          '@nestjs/platform-express': '^12.0.1',
        },
      },
      null,
      2,
    ),
  );
  tree.create('pnpm-lock.yaml', '');
  tree.create('nest-cli.json', JSON.stringify({ sourceRoot: 'src' }));
  tree.create(
    'src/main.ts',
    `import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module${ext}';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(process.env.PORT ?? 3000);
}
await bootstrap();
`,
  );
  tree.create(
    'src/app.module.ts',
    `import { Module } from '@nestjs/common';
import { AppController } from './app.controller${ext}';
import { AppService } from './app.service${ext}';

@Module({
  imports: [],
  controllers: [AppController],
  providers: [AppService],
})
export class AppModule {}
`,
  );
  return tree;
}
